/**
 * Pins the client preview mirror to the server's NutritionPlan: the fixtures
 * are generated by running app/Services/NutritionPlan.php, so a drift in either side fails here.
 */
import { describe, expect, it } from "@jest/globals";

import fixtures from "@/utils/nutrition.fixtures.json";
import { computeNutritionPreview, type PhysicalInputs } from "@/utils/nutrition";

describe("nutrition preview mirrors app/Services/NutritionPlan.php", () => {
  for (const { input, expected } of fixtures as {
    input: PhysicalInputs;
    expected: Record<string, unknown>;
  }[]) {
    it(`${input.gender} ${input.age}y ${input.currentWeight}→${input.targetWeight}kg ${input.activityLevel}`, () => {
      expect(computeNutritionPreview(input)).toEqual(expected);
    });
  }
});
